/* Number → English words, for the "Amount in Words" line on the proforma invoice */
function numberToWords(num) {
  const ones = ["", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten",
    "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"];
  const tens = ["", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"];
  function chunk(n) {
    if (n === 0) return "";
    if (n < 20) return ones[n] + " ";
    if (n < 100) return tens[Math.floor(n / 10)] + " " + chunk(n % 10);
    return ones[Math.floor(n / 100)] + " Hundred " + chunk(n % 100);
  }
  function convert(n) {
    if (n === 0) return "Zero";
    let str = "";
    const billions = Math.floor(n / 1e9); n %= 1e9;
    const millions = Math.floor(n / 1e6); n %= 1e6;
    const thousands = Math.floor(n / 1e3); n %= 1e3;
    if (billions) str += chunk(billions) + "Billion ";
    if (millions) str += chunk(millions) + "Million ";
    if (thousands) str += chunk(thousands) + "Thousand ";
    if (n) str += chunk(n);
    return str.trim();
  }
  const whole = Math.floor(Math.abs(num));
  const cents = Math.round((Math.abs(num) - whole) * 100);
  let words = "Kenya Shillings " + convert(whole);
  if (cents) words += " and " + convert(cents) + " Cents";
  return words + " Only";
}

