/* ============================================================================
   SIZING ENGINE — replicates "1. Sizing" sheet formulas exactly
   ============================================================================ */
function computeSizing(appliances, settings) {
  const totalDailyWh = appliances.reduce((s, a) => s + a.unitW * a.qty * a.dayHrs, 0);
  const totalNightWh = appliances.reduce((s, a) => s + a.unitW * a.qty * a.nightHrs, 0);
  const totalPeakW = appliances.reduce((s, a) => s + a.unitW * a.qty, 0);

  const scenarios = {};
  for (const dc of DESIGN_CASES) {
    const f = dc.key;
    const designDailyKwh = (totalDailyWh / 1000) * f;
    const designNightKwh = (totalNightWh / 1000) * f;
    const designPeakKw = (totalPeakW / 1000) * f;

    const arrayLoadW = (designDailyKwh / settings.sizingSunHours) * 1000 / settings.derateFactor;
    const panelsCalc = arrayLoadW / settings.panelRatingW;
    const panels = Math.ceil(panelsCalc);
    const installedKwp = (panels * settings.panelRatingW) / 1000;
    const annualGenKwh = installedKwp * settings.yieldSunHours * settings.daysPerMonth * 12;
    const annualSavingKES = annualGenKwh * settings.tariff;

    const batteryCapReqKwh = designNightKwh / (settings.efficiency * settings.dod);
    const batteriesCalc = batteryCapReqKwh / settings.batteryKwh;
    const batteries = settings.batteryRoundUp ? Math.ceil(batteriesCalc) : Math.round(batteriesCalc);
    const batteryBankKwh = batteries * settings.batteryKwh;

    const inverterReqKw = designPeakKw * settings.inverterSafetyFactor;
    const recommended = INVERTER_OPTIONS.find((o) => o.kw >= inverterReqKw) || INVERTER_OPTIONS[INVERTER_OPTIONS.length - 1];

    scenarios[dc.key] = {
      designDailyKwh, designNightKwh, designPeakKw, arrayLoadW, panelsCalc, panels,
      installedKwp, annualGenKwh, annualSavingKES, batteryCapReqKwh, batteriesCalc,
      batteries, batteryBankKwh, inverterReqKw, recommendedInverter: recommended,
    };
  }
  return { totalDailyWh, totalNightWh, totalPeakW, scenarios };
}

/* ============================================================================
   BOM ENGINE — replicates "2. BOM Builder" quantity-rule logic
   ============================================================================ */
function driverValue(rule, ctx) {
  switch (rule) {
    case "Per Panel": return ctx.panels;
    case "Per Battery": return ctx.batteries;
    case "Per Inverter kW": return ctx.inverterKw;
    case "Per Watt Installed": return ctx.installedKwp * 1000;
    case "Fixed": return 1;
    case "Per Metre - Array to Inverter": return ctx.siteVars.arrayToInverterM;
    case "Per Metre - Inverter to DB": return ctx.siteVars.inverterToDBM;
    case "Per Metre - Battery to Inverter": return ctx.siteVars.batteryToInverterM;
    case "Per String": return ctx.siteVars.numStrings;
    case "Manual": return 0;
    default: return 0;
  }
}

function buildBOM(lead, sizing, settings, catalog) {
  const sc = sizing.scenarios[lead.designCase];
  const ctx = {
    panels: sc.panels,
    batteries: sc.batteries,
    inverterKw: sc.recommendedInverter.kw,
    installedKwp: sc.installedKwp,
    siteVars: lead.siteVars,
  };
  const markup = lead.markupOverride ?? settings.markup; // per-lead margin test/override, else the global default

  const lines = [];

  // Core: Solar PV panels
  const panelItem = catalog.find((c) => c.id === "panel") || DEFAULT_CATALOG[0];
  lines.push(makeLine("core-panel", "Solar PV", panelItem.description, "Per Panel", sc.panels, panelItem.buyPrice, panelItem.vatExempt, lead.bomOverrides["core-panel"], true));

  // Core: Inverter (from sizing recommendation)
  lines.push(makeLine("core-inverter", "Inverter", sc.recommendedInverter.desc, "Fixed", 1, sc.recommendedInverter.price, true, lead.bomOverrides["core-inverter"], true));

  // Core: Batteries
  const battItem = catalog.find((c) => c.id === "battery") || DEFAULT_CATALOG[1];
  lines.push(makeLine("core-battery", "Batteries", battItem.description, "Per Battery", sc.batteries, battItem.buyPrice, battItem.vatExempt, lead.bomOverrides["core-battery"], true));

  // Catalog-driven lines (structure, cabling, accessories, logistics, and any technician-added catalog items)
  for (const item of catalog) {
    if (item.core) continue; // panel/battery core already handled above
    const dv = driverValue(item.quantityRule, ctx);
    const calcQty = item.quantityRule === "Manual" ? 0 : Math.ceil(dv * item.factor);
    lines.push(makeLine(item.id, item.category, item.description, item.quantityRule, calcQty, item.buyPrice, item.vatExempt, lead.bomOverrides[item.id], false));
  }

  // Technician free-form extra items (fully custom, no catalog quantity rule needed)
  for (const ex of lead.extraItems) {
    lines.push({
      id: ex.id, category: ex.category || "Other / Additional Items", description: ex.description || "(untitled item)",
      quantityRule: "Manual", calcQty: 0, finalQty: ex.qty || 0, inc: ex.inc,
      unitCost: ex.unitCost || 0, unitPrice: (ex.unitCost || 0) * (1 + markup),
      vatExempt: !!ex.vatExempt, isCore: false, isExtra: true,
    });
  }

  function markupPass(l) {
    l.unitPrice = l.unitCostUsed * (1 + markup);
    l.lineTotal = l.inc ? l.finalQty * l.unitPrice : 0;
    l.vat = l.vatExempt || !l.inc ? 0 : l.lineTotal * settings.vat;
    l.lineCost = l.inc ? l.finalQty * l.unitCostUsed : 0;
    l.profit = l.lineTotal - l.lineCost;
    return l;
  }

  return lines.map((l) => (l.isExtra ? finalizeExtra(l, settings, markup) : markupPass(l)));
}

// Flags when a core line's quantity has been overridden away from its calculated requirement.
// This exists because the source spreadsheets this app replaces had a manual "rounded panel
// count" cell that drifted from its own calculation in 20 of 27 real client tabs we audited —
// silently, with no warning. This makes that drift visible instead of invisible.
function sizingDeviation(line) {
  if (!line.isCore) return null;
  const { calcQty, finalQty } = line;
  if (calcQty <= 0) {
    if (finalQty === calcQty) return null;
    return { pct: finalQty > calcQty ? `+${finalQty - calcQty}` : `${finalQty - calcQty}`, severe: true };
  }
  const ratio = finalQty / calcQty;
  if (ratio >= 0.9 && ratio <= 1.15) return null;
  const pctNum = Math.round((ratio - 1) * 100);
  return { pct: `${pctNum > 0 ? "+" : ""}${pctNum}%`, severe: ratio > 1.5 || ratio < 0.5 };
}

function makeLine(id, category, description, quantityRule, calcQty, buyPrice, vatExempt, override, isCore) {
  const inc = override?.inc ?? true;
  const finalQty = override?.qtyOverride ?? calcQty;
  const unitCostUsed = override?.costOverride ?? buyPrice;
  return { id, category, description, quantityRule, calcQty, finalQty, inc, unitCostUsed, vatExempt, isCore };
}
function finalizeExtra(l, settings, markup) {
  l.unitPrice = l.unitCost * (1 + markup);
  l.lineTotal = l.inc ? l.finalQty * l.unitPrice : 0;
  l.vat = l.vatExempt || !l.inc ? 0 : l.lineTotal * settings.vat;
  l.lineCost = l.inc ? l.finalQty * l.unitCost : 0;
  l.profit = l.lineTotal - l.lineCost;
  return l;
}

function bomTotals(lines) {
  const subTotal = lines.reduce((s, l) => s + l.lineTotal, 0);
  const vat = lines.reduce((s, l) => s + l.vat, 0);
  const cost = lines.reduce((s, l) => s + l.lineCost, 0);
  const profit = lines.reduce((s, l) => s + l.profit, 0);
  const costExempt = lines.reduce((s, l) => s + (l.inc && l.vatExempt ? l.lineCost : 0), 0);
  const costTaxable = lines.reduce((s, l) => s + (l.inc && !l.vatExempt ? l.lineCost : 0), 0);
  return { subTotal, vat, total: subTotal + vat, cost, profit, margin: subTotal ? profit / subTotal : 0, costExempt, costTaxable };
}

// Recomputes Sub Total / VAT / Total / Profit at a hypothetical markup, purely from each line's
// cost (markup-independent) — used by the margin-testing tool so it can preview instantly without
// rebuilding the whole BOM. lineTotal = lineCost * (1 + markup) by construction, so this is exact.
function totalsAtMarkup(totals, vatRate, markup) {
  const subTotal = totals.costExempt * (1 + markup) + totals.costTaxable * (1 + markup);
  const vat = totals.costTaxable * (1 + markup) * vatRate;
  const profit = subTotal - totals.cost;
  return { subTotal, vat, total: subTotal + vat, cost: totals.cost, profit, margin: subTotal ? profit / subTotal : 0 };
}

function costByCategory(lines) {
  const byCat = {};
  for (const cat of CORE_CATEGORIES) byCat[cat] = 0;
  let other = 0;
  for (const l of lines) {
    if (!l.inc) continue;
    if (CORE_CATEGORIES.includes(l.category)) byCat[l.category] += l.lineCost;
    else other += l.lineCost;
  }
  return { byCat, other };
}

function quoteByCategory(lines) {
  const byCat = {};
  for (const cat of CORE_CATEGORIES) byCat[cat] = { qty: 0, total: 0, count: 0 };
  let other = { total: 0, count: 0 };
  for (const l of lines) {
    if (!l.inc) continue;
    if (CORE_CATEGORIES.includes(l.category)) {
      byCat[l.category].qty += l.finalQty;
      byCat[l.category].total += l.lineTotal;
      byCat[l.category].count += 1;
    } else {
      other.total += l.lineTotal;
      other.count += 1;
    }
  }
  return { byCat, other };
}

/* ============================================================================
   STORAGE HOOK
   ============================================================================ */
function usePersistentState(key, initial) {
  const [state, setState] = useState(initial);
  const [loaded, setLoaded] = useState(false);
  useEffect(() => {
    let mounted = true;
    (async () => {
      try {
        const res = await window.storage?.get(key, false);
        if (mounted && res?.value) setState(JSON.parse(res.value));
      } catch (e) { /* key doesn't exist yet — use initial */ }
      if (mounted) setLoaded(true);
    })();
    return () => { mounted = false; };
  }, [key]);
  useEffect(() => {
    if (!loaded) return;
    (async () => {
      try { await window.storage?.set(key, JSON.stringify(state), false); }
      catch (e) { console.error("storage save failed", e); }
    })();
  }, [key, state, loaded]);
  return [state, setState, loaded];
}

