function leadFinancials(lead, settings, catalog) {
  const sizing = computeSizing(lead.appliances, settings);
  const bomLines = buildBOM(lead, sizing, settings, catalog);
  const totals = bomTotals(bomLines);
  const netDue = totals.total - (lead.tradeInCredit || 0);
  const received = lead.amountReceived || 0;
  return { totals, netDue, received, balance: netDue - received };
}

function downloadWorkbook(sheetName, headers, rows, filename) {
  const ws = XLSX.utils.aoa_to_sheet([headers, ...rows]);
  ws["!cols"] = headers.map((h) => ({ wch: Math.max(14, h.length + 2) }));
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, sheetName);
  XLSX.writeFile(wb, filename);
}

function Dashboard({ leads, settings, catalog, setRoute }) {
  const stats = useMemo(() => {
    const fin = leads.map((l) => ({ lead: l, ...leadFinancials(l, settings, catalog) }));
    const totalLeads = leads.length;
    const accepted = leads.filter((l) => l.outcome === "Accepted").length;
    const rejected = leads.filter((l) => l.outcome === "Rejected").length;
    const pending = totalLeads - accepted - rejected;
    const active = leads.filter((l) => l.outcome === "Accepted" && l.status !== "Invoiced").length;
    const activeValue = fin.filter((f) => f.lead.outcome === "Accepted" && f.lead.status !== "Invoiced").reduce((s, f) => s + f.totals.total, 0);
    const completed = leads.filter((l) => l.outcome === "Accepted" && l.status === "Invoiced").length;
    const revenueRecognized = fin.filter((f) => f.lead.outcome === "Accepted" && f.lead.status === "Invoiced").reduce((s, f) => s + f.netDue, 0);
    const invoiced = fin.filter((f) => f.lead.status === "Invoiced");
    const pipelineValue = fin.filter((f) => f.lead.outcome !== "Rejected").reduce((s, f) => s + f.totals.total, 0);
    const invoicedRevenue = invoiced.reduce((s, f) => s + f.netDue, 0);
    const collected = invoiced.reduce((s, f) => s + f.received, 0);
    const outstanding = invoiced.reduce((s, f) => s + Math.max(0, f.balance), 0);
    const avgDeal = totalLeads ? fin.reduce((s, f) => s + f.totals.total, 0) / totalLeads : 0;
    const conversionRate = totalLeads ? accepted / totalLeads : 0;
    const winRate = (accepted + rejected) ? accepted / (accepted + rejected) : 0;

    // last 6 months revenue (by dateIssued for invoiced leads, falling back to createdAt)
    const now = new Date();
    const months = Array.from({ length: 6 }, (_, i) => {
      const d = new Date(now.getFullYear(), now.getMonth() - (5 - i), 1);
      return { key: `${d.getFullYear()}-${d.getMonth()}`, label: d.toLocaleString("en-US", { month: "short" }) };
    });
    const monthly = months.map((m) => ({ ...m, value: 0 }));
    invoiced.forEach((f) => {
      const dateStr = f.lead.dateIssued || f.lead.createdAt;
      if (!dateStr) return;
      const d = new Date(dateStr);
      const key = `${d.getFullYear()}-${d.getMonth()}`;
      const bucket = monthly.find((m) => m.key === key);
      if (bucket) bucket.value += f.totals.total;
    });

    const recent = [...leads].sort((a, b) => (b.createdAt || "").localeCompare(a.createdAt || "")).slice(0, 6);

    return { fin, totalLeads, accepted, rejected, pending, active, activeValue, completed, revenueRecognized, pipelineValue, invoicedRevenue, collected, outstanding, avgDeal, conversionRate, winRate, monthly, recent };
  }, [leads, settings, catalog]);

  const exportContacts = () => {
    const headers = ["Client Name", "Phone", "Email", "Location", "Type", "Contact Person", "PIN", "Contractor", "Project Type", "Status", "Outcome", "Date Logged"];
    const rows = leads.map((l) => [
      l.client.name, l.client.phone, l.client.email, l.client.location,
      l.client.isCommercial ? "Commercial" : "Residential", l.client.contactPerson, l.client.pin,
      l.client.contractor, l.client.projectType, l.status, l.outcome || "Pending", l.createdAt,
    ]);
    downloadWorkbook("Contacts", headers, rows, "Client_Contacts.xlsx");
  };

  const exportRegister = () => {
    const headers = ["Client Name", "REF", "Status", "Outcome", "Total (KES)", "Net Due (KES)", "Received (KES)", "Balance (KES)", "Date Logged", "Date Issued"];
    const rows = stats.fin.map((f) => [
      f.lead.client.name, f.lead.refNo || "—", f.lead.status, f.lead.outcome || "Pending",
      Math.round(f.totals.total), Math.round(f.netDue), Math.round(f.received), Math.round(f.balance),
      f.lead.createdAt, f.lead.dateIssued || "",
    ]);
    downloadWorkbook("Register", headers, rows, "Leads_Invoice_Register.xlsx");
  };

  const maxMonthly = Math.max(1, ...stats.monthly.map((m) => m.value));

  return (
    <div className="space-y-5">
      <div>
        <h1 className="text-xl font-bold text-slate-800">Dashboard</h1>
        <p className="text-sm text-slate-500">Business at a glance, across all {stats.totalLeads} logged leads.</p>
      </div>

      <Card className="p-0 overflow-hidden">
        <div className="flex overflow-x-auto divide-x divide-slate-100">
          <KpiPane icon={<Wrench size={16} />} label="Active Projects" value={stats.active} accent="#EA580C" />
          <KpiPane icon={<PackageCheck size={16} />} label="Completed Projects" value={stats.completed} accent="#7C3AED" />
          <KpiPane icon={<Percent size={16} />} label="Conversion Rate" value={`${fmtNum(stats.conversionRate * 100, 0)}%`} sub={`${stats.accepted} of ${stats.totalLeads} leads`} accent="#0891B2" />
          <KpiPane icon={<TrendingUp size={16} />} label="Win Rate" value={`${fmtNum(stats.winRate * 100, 0)}%`} sub={`of ${stats.accepted + stats.rejected} decided`} accent="#059669" />
          <KpiPane icon={<Wallet size={16} />} label="Active Project Value" value={fmtKES(stats.activeValue)} accent="#EA580C" tintAlpha="26" />
          <KpiPane icon={<Receipt size={16} />} label="Revenue Recognized" value={fmtKES(stats.revenueRecognized)} accent="#7C3AED" highlight highlightBg="#4C1D95" highlightBar="#C4B5FD" />
          <KpiPane icon={<Wallet size={16} />} label="Pipeline Value" value={fmtKES(stats.pipelineValue)} accent={BRAND.navy} highlight />
        </div>
      </Card>

      <Card className="p-5">
        <SectionLabel>Invoiced revenue — last 6 months</SectionLabel>
        <div className="flex items-end gap-4 h-40 mt-4 px-2">
          {stats.monthly.map((m) => (
            <div key={m.key} className="flex-1 flex flex-col items-center justify-end gap-1.5">
              <div className="text-xs font-semibold text-slate-600">{m.value > 0 ? fmtNum(m.value / 1000, 0) + "k" : ""}</div>
              <div className="w-full rounded-t-md transition-all" style={{ height: `${Math.max(4, (m.value / maxMonthly) * 100)}%`, background: `linear-gradient(180deg, ${BRAND.gold}, #F2C664)` }} />
              <div className="text-xs text-slate-400 font-medium">{m.label}</div>
            </div>
          ))}
        </div>
      </Card>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        <Card className="p-5">
          <div className="flex items-center justify-between mb-3">
            <SectionLabel>Recent leads</SectionLabel>
            <button onClick={() => setRoute({ view: "list" })} className="text-xs font-semibold hover:underline" style={{ color: BRAND.navy }}>View all</button>
          </div>
          <div className="space-y-2">
            {stats.recent.length === 0 && <div className="text-sm text-slate-400 text-center py-6">No leads yet.</div>}
            {stats.recent.map((l) => (
              <div key={l.id} className="flex items-center justify-between text-sm py-1.5 border-b border-slate-100 last:border-0 cursor-pointer" onClick={() => setRoute({ view: "detail", leadId: l.id, tab: "info" })}>
                <div className="flex items-center gap-2 min-w-0">
                  <span className="truncate font-medium text-slate-700">{l.client.name}</span>
                  <LeadSummaryBadge lead={l} />
                </div>
                <span className="text-xs text-slate-400 shrink-0">{l.createdAt}</span>
              </div>
            ))}
          </div>
        </Card>

        <Card className="p-5">
          <SectionLabel>Download reports</SectionLabel>
          <p className="text-xs text-slate-500 mb-3">Exports every logged lead as a real .xlsx file — nothing leaves your browser.</p>
          <div className="space-y-2">
            <button onClick={exportContacts} className="w-full flex items-center justify-between gap-2 text-sm font-medium px-3 py-2.5 rounded-lg border border-slate-200 hover:bg-slate-50">
              <span className="flex items-center gap-2"><Contact size={15} className="text-slate-400" /> Client Contacts</span>
              <Download size={14} className="text-slate-400" />
            </button>
            <button onClick={exportRegister} className="w-full flex items-center justify-between gap-2 text-sm font-medium px-3 py-2.5 rounded-lg border border-slate-200 hover:bg-slate-50">
              <span className="flex items-center gap-2"><FileSpreadsheet size={15} className="text-slate-400" /> Leads &amp; Invoice Register</span>
              <Download size={14} className="text-slate-400" />
            </button>
          </div>
          <div className="mt-4 pt-4 border-t border-slate-100 grid grid-cols-2 gap-3 text-center">
            <div><div className="text-sm font-bold text-slate-800">{fmtKES(stats.avgDeal)}</div><div className="text-xs text-slate-400">Avg. deal size</div></div>
            <div><div className="text-sm font-bold text-slate-800">{fmtKES(stats.collected)}</div><div className="text-xs text-slate-400">Total collected</div></div>
          </div>
        </Card>
      </div>
    </div>
  );
}
function KpiPane({ icon, label, value, sub, accent, highlight, highlightBg, highlightBar, tintAlpha = "0D" }) {
  const fillColor = highlightBg || BRAND.navy;
  const bg = highlight ? fillColor : `${accent}${tintAlpha}`;
  const valueColor = highlight ? "#fff" : accent;
  return (
    <div className="flex-1 px-4 py-4 relative" style={{ minWidth: 150, background: bg, color: highlight ? "#fff" : undefined }}>
      <div className="absolute top-0 left-0 right-0 h-1" style={{ background: highlight ? (highlightBar || BRAND.gold) : accent }} />
      <div className="flex items-center gap-2 mb-2">
        <div className="w-7 h-7 rounded-lg flex items-center justify-center shrink-0" style={{ background: highlight ? "rgba(255,255,255,0.15)" : `${accent}26`, color: highlight ? "#fff" : accent }}>
          {icon}
        </div>
        <div className={`text-xs font-medium ${highlight ? "text-blue-200" : "text-slate-500"}`}>{label}</div>
      </div>
      <div className="text-xl font-bold tracking-tight" style={{ color: valueColor }}>{value}</div>
      {sub && <div className={`text-xs mt-0.5 ${highlight ? "text-blue-200" : "text-slate-400"}`}>{sub}</div>}
    </div>
  );
}

function LeadsList({ leads, setLeads, createLead, setRoute }) {
  const [q, setQ] = useState("");
  const [filter, setFilter] = useState("All"); // All | Pending | Accepted | Rejected
  const deleteLead = (id) => setLeads((prev) => prev.filter((l) => l.id !== id));
  const setOutcome = (id, v) => setLeads((prev) => prev.map((l) => (l.id === id ? { ...l, outcome: v } : l)));
  const setStatus = (id, v) => setLeads((prev) => prev.map((l) => (l.id === id ? { ...l, status: v } : l)));
  const setStarted = (id, v) => setLeads((prev) => prev.map((l) => (l.id === id ? { ...l, started: v } : l)));

  const byFilter = leads.filter((l) => filter === "All" ? true : filter === "Pending" ? !l.outcome : l.outcome === filter);
  const filtered = byFilter.filter((l) => (l.client.name + l.client.location).toLowerCase().includes(q.toLowerCase()));

  const counts = {
    All: leads.length,
    Pending: leads.filter((l) => !l.outcome).length,
    Accepted: leads.filter((l) => l.outcome === "Accepted").length,
    Rejected: leads.filter((l) => l.outcome === "Rejected").length,
  };
  const filterTone = { All: BRAND.navy, Pending: "#64748B", Accepted: "#059669", Rejected: "#E11D48" };

  return (
    <div>
      <div className="flex items-center justify-between mb-5 gap-3 flex-wrap">
        <div>
          <h1 className="text-xl font-bold text-slate-800">Leads &amp; Jobs</h1>
          <p className="text-sm text-slate-500">Log a lead, size the system from usage data, then build the BOM and quote.</p>
        </div>
        <button onClick={createLead} className="flex items-center gap-1.5 text-white px-4 py-2 rounded-lg text-sm font-semibold transition" style={{ background: BRAND.navy }} onMouseOver={(e)=>e.currentTarget.style.background=BRAND.navyDark} onMouseOut={(e)=>e.currentTarget.style.background=BRAND.navy}>
          <Plus size={16} /> New Lead
        </button>
      </div>

      <div className="flex items-center gap-4 mb-4 flex-wrap">
        <div className="relative max-w-sm flex-1">
          <Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
          <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search leads..." className="w-full pl-9 pr-3 py-2 rounded-lg border border-slate-300 text-sm focus:outline-none focus:ring-2" />
        </div>
        <div className="flex items-center gap-1.5">
          {["All", "Pending", "Accepted", "Rejected"].map((f) => (
            <button
              key={f}
              onClick={() => setFilter(f)}
              style={filter === f ? { background: filterTone[f], color: "#FFFFFF" } : { background: "#F1F5F9", color: "#64748B" }}
              className="px-3 py-1.5 rounded-lg text-xs font-semibold transition"
            >
              {f} <span className="opacity-70">({counts[f]})</span>
            </button>
          ))}
        </div>
      </div>

      {filtered.length === 0 && (
        <Card className="p-10 text-center text-slate-400">
          <PackagePlus size={32} className="mx-auto mb-3 text-slate-300" />
          {leads.length === 0 ? "No leads yet. Log your first one to get started." : "No leads match this view."}
        </Card>
      )}

      <div className="grid gap-3">
        {filtered.map((l) => {
          const sizing = computeSizing(l.appliances, DEFAULT_SETTINGS);
          const sc = sizing.scenarios[l.designCase];
          return (
            <Card key={l.id} className="p-4 flex items-center justify-between gap-4 hover:shadow-md transition cursor-pointer" onClick={() => setRoute({ view: "detail", leadId: l.id, tab: "info" })}>
              <div className="min-w-0">
                <div className="flex items-center gap-2 mb-0.5 flex-wrap">
                  <span className="font-semibold text-slate-800 truncate">{l.client.name}</span>
                  <LeadSummaryBadge lead={l} />
                </div>
                <div className="text-xs text-slate-500 truncate">{l.client.location || "No location set"} • {l.client.projectType}</div>
              </div>
              <div className="hidden md:flex items-center gap-4 text-xs text-slate-500 shrink-0">
                <div className="text-center"><div className="font-semibold text-slate-700">{sc.panels}</div>panels</div>
                <div className="text-center"><div className="font-semibold text-slate-700">{sc.batteries}</div>batt.</div>
                <div className="text-center"><div className="font-semibold text-slate-700">{sc.recommendedInverter.kw}kW</div>inv.</div>
                <div className="text-center"><div className="font-semibold text-slate-700">{l.createdAt}</div>logged</div>
              </div>
              <div className="flex items-center gap-2 shrink-0" onClick={(e) => e.stopPropagation()}>
                <OutcomeControl
                  outcome={l.outcome} onChange={(v) => setOutcome(l.id, v)}
                  started={l.started} onStartedChange={(v) => setStarted(l.id, v)}
                  status={l.status} onStatusChange={(v) => setStatus(l.id, v)}
                  onEdit={() => setRoute({ view: "detail", leadId: l.id, tab: "info" })}
                  size="small"
                />
                <button onClick={() => { if (confirm(`Delete lead "${l.client.name}"?`)) deleteLead(l.id); }} className="p-2 text-slate-300 hover:text-rose-500 transition">
                  <Trash2 size={15} />
                </button>
                <ChevronRight size={18} className="text-slate-300" />
              </div>
            </Card>
          );
        })}
      </div>
    </div>
  );
}

