/* ---------------------------- Usage data import (client-filled Google Sheet, exported as .xlsx/.csv) ---------------------------- */
function pickField(row, patterns) {
  const keys = Object.keys(row);
  for (const p of patterns) {
    const hit = keys.find((k) => k.toLowerCase().trim().includes(p));
    if (hit !== undefined && String(row[hit]).trim() !== "") return row[hit];
  }
  return undefined;
}
function normalizeApplianceRows(rows) {
  const out = [];
  for (const row of rows) {
    const name = pickField(row, ["appliance", "item", "description", "name"]);
    const unitW = pickField(row, ["unit power", "power (w)", "watt", "power"]);
    const qty = pickField(row, ["qty", "quantity", "number", "no."]);
    const dayHrs = pickField(row, ["day hours", "daily hours", "day"]);
    const nightHrs = pickField(row, ["night hours", "night"]);
    if (name === undefined && unitW === undefined) continue; // skip blank/decorative rows
    out.push({
      id: UID(),
      name: String(name ?? "Item").trim(),
      unitW: Number(unitW) || 0,
      qty: Number(qty) || 1,
      dayHrs: Number(dayHrs) || 0,
      nightHrs: Number(nightHrs) || 0,
    });
  }
  return out;
}
function parseUsageFile(file, onDone, onError) {
  const reader = new FileReader();
  reader.onload = (e) => {
    try {
      const data = new Uint8Array(e.target.result);
      const wb = XLSX.read(data, { type: "array" });
      const ws = wb.Sheets[wb.SheetNames[0]];
      const rows = XLSX.utils.sheet_to_json(ws, { defval: "" });
      const appliances = normalizeApplianceRows(rows);
      if (appliances.length === 0) throw new Error("No usable rows found — check the column headers match the template.");
      onDone(appliances);
    } catch (err) {
      onError(err);
    }
  };
  reader.onerror = () => onError(new Error("Could not read the file."));
  reader.readAsArrayBuffer(file);
}
function downloadApplianceTemplate() {
  const headers = ["Appliance", "Unit Power (W)", "Quantity", "Daily Hours", "Night Hours"];
  const example = APPLIANCE_PRESETS.map((p) => [p.name, p.unitW, p.qty, p.dayHrs, p.nightHrs]);
  const ws = XLSX.utils.aoa_to_sheet([headers, ...example]);
  ws["!cols"] = [{ wch: 20 }, { wch: 15 }, { wch: 10 }, { wch: 12 }, { wch: 12 }];
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "Usage Data");
  XLSX.writeFile(wb, "appliance-usage-template.xlsx");
}

function UploadUsageData({ onImport }) {
  const fileRef = useRef(null);
  const [msg, setMsg] = useState(null); // { type: "ok"|"error", text }

  const handleFile = (file) => {
    if (!file) return;
    parseUsageFile(
      file,
      (appliances) => setMsg({ type: "ok", text: `Parsed ${appliances.length} row${appliances.length !== 1 ? "s" : ""} from "${file.name}". Choose how to add them below.`, appliances }),
      (err) => setMsg({ type: "error", text: err.message })
    );
  };

  return (
    <div className="border border-dashed border-slate-300 rounded-lg p-3 mb-3 bg-slate-50">
      <div className="flex items-center justify-between flex-wrap gap-2">
        <div className="flex items-center gap-2 text-sm text-slate-600">
          <FileSpreadsheet size={16} className="text-slate-400" />
          <span>Client filled in a Google Sheet? Download it as .xlsx or .csv and upload here.</span>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={downloadApplianceTemplate} className="flex items-center gap-1 text-xs font-semibold px-2.5 py-1.5 rounded-lg border border-slate-300 text-slate-600 hover:bg-white">
            <Download size={13} /> Download template
          </button>
          <button onClick={() => fileRef.current?.click()} className="flex items-center gap-1 text-xs font-semibold px-2.5 py-1.5 rounded-lg text-white" style={{ background: BRAND.navy }}>
            <Upload size={13} /> Upload file
          </button>
          <input ref={fileRef} type="file" accept=".xlsx,.xls,.csv" className="hidden" onChange={(e) => handleFile(e.target.files?.[0])} />
        </div>
      </div>
      {msg && (
        <div className={`mt-2 text-xs rounded-lg p-2 ${msg.type === "error" ? "bg-rose-50 text-rose-600" : "bg-emerald-50 text-emerald-700"}`}>
          <div className="flex items-start justify-between gap-2">
            <span>{msg.type === "error" ? <AlertTriangle size={12} className="inline mr-1" /> : <Check size={12} className="inline mr-1" />}{msg.text}</span>
            <button onClick={() => setMsg(null)} className="shrink-0 text-slate-400 hover:text-slate-600"><X size={12} /></button>
          </div>
          {msg.type === "ok" && (
            <div className="flex gap-2 mt-2">
              <button onClick={() => { onImport(msg.appliances, "replace"); setMsg(null); }} className="text-xs font-semibold px-2.5 py-1 rounded-lg bg-white border border-emerald-300 text-emerald-700 hover:bg-emerald-100">Replace all appliances</button>
              <button onClick={() => { onImport(msg.appliances, "append"); setMsg(null); }} className="text-xs font-semibold px-2.5 py-1 rounded-lg bg-white border border-emerald-300 text-emerald-700 hover:bg-emerald-100">Add to existing list</button>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

/* ---------------------------- Usage & Sizing Tab ---------------------------- */
