function Row({ icon, label, value }) {
  return <div className="flex items-center justify-between text-slate-600"><span className="flex items-center gap-1">{icon}{label}</span><span className="font-semibold text-slate-800">{value}</span></div>;
}

/* ---------------------------- BOM Tab ---------------------------- */
function MarginTester({ lead, settings, totals, updateLead }) {
  const activeMarkup = lead.markupOverride ?? settings.markup;
  const [testMarkup, setTestMarkup] = useState(activeMarkup);
  const preview = totalsAtMarkup(totals, settings.vat, testMarkup);
  const isTesting = Math.abs(testMarkup - activeMarkup) > 0.0001;
  const isOverridden = lead.markupOverride != null;

  return (
    <Card className="p-5">
      <div className="flex items-center justify-between mb-1">
        <SectionLabel>Test a different profit margin</SectionLabel>
        {isOverridden && <Badge tone="amber">Using {fmtNum(activeMarkup * 100, 1)}% override, not the {fmtNum(settings.markup * 100, 1)}% default</Badge>}
      </div>
      <div className="flex items-center gap-4 mb-4">
        <input
          type="range" min="0" max="0.6" step="0.01" value={testMarkup}
          onChange={(e) => setTestMarkup(+e.target.value)}
          className="flex-1"
          style={{ accentColor: BRAND.navy }}
        />
        <div className="w-20 text-right font-mono font-bold text-lg" style={{ color: BRAND.navy }}>{fmtNum(testMarkup * 100, 1)}%</div>
      </div>

      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-4">
        <Stat label="Sub Total @ test" value={fmtKES(preview.subTotal)} />
        <Stat label="Total @ test" value={fmtKES(preview.total)} />
        <Stat label="Profit @ test" value={fmtKES(preview.profit)} tone="green" />
        <Stat label="Margin @ test" value={`${fmtNum(preview.margin * 100, 1)}%`} />
      </div>

      {isTesting && (
        <div className="text-xs text-slate-500 mb-3">
          vs. current: {preview.total >= totals.total ? "+" : ""}{fmtNum(preview.total - totals.total, 0)} KES on the total, {preview.profit >= totals.profit ? "+" : ""}{fmtNum(preview.profit - totals.profit, 0)} KES on profit.
        </div>
      )}

      <div className="flex items-center gap-2 flex-wrap">
        <button
          onClick={() => updateLead({ markupOverride: testMarkup })}
          className="text-xs font-semibold px-3 py-1.5 rounded-lg text-white"
          style={{ background: BRAND.navy }}
        >
          Apply {fmtNum(testMarkup * 100, 1)}% to this quote
        </button>
        {isOverridden && (
          <button
            onClick={() => { updateLead({ markupOverride: null }); setTestMarkup(settings.markup); }}
            className="text-xs font-semibold px-3 py-1.5 rounded-lg border border-slate-300 text-slate-500 hover:bg-slate-50"
          >
            Revert to default ({fmtNum(settings.markup * 100, 1)}%)
          </button>
        )}
        <span className="text-xs text-slate-400">Moving the slider only previews — nothing changes until you apply it.</span>
      </div>
    </Card>
  );
}

function BomTab({ lead, settings, catalog, sizing, bomLines, totals, updateLead, onNext }) {
  const sc = sizing.scenarios[lead.designCase];

  const setOverride = (id, patch) => updateLead((l) => ({ bomOverrides: { ...l.bomOverrides, [id]: { ...l.bomOverrides[id], ...patch } } }));
  const addExtra = () => updateLead((l) => ({ extraItems: [...l.extraItems, { id: UID(), category: "", description: "", qty: 1, unitCost: 0, vatExempt: false, inc: true }] }));
  const updateExtra = (id, patch) => updateLead((l) => ({ extraItems: l.extraItems.map((x) => (x.id === id ? { ...x, ...patch } : x)) }));
  const removeExtra = (id) => updateLead((l) => ({ extraItems: l.extraItems.filter((x) => x.id !== id) }));

  const coreLines = bomLines.filter((l) => l.isCore);
  const catalogLines = bomLines.filter((l) => !l.isCore && !l.isExtra);
  const extraLines = bomLines.filter((l) => l.isExtra);

  return (
    <div className="space-y-5">
      <div className="grid grid-cols-3 sm:grid-cols-5 gap-3">
        <Stat label="Sub Total" value={fmtKES(totals.subTotal)} />
        <Stat label="VAT" value={fmtKES(totals.vat)} />
        <Stat label="Total" value={fmtKES(totals.total)} tone="navy" />
        <Stat label="Profit" value={fmtKES(totals.profit)} tone="green" />
        <Stat label="Margin" value={`${fmtNum(totals.margin * 100, 1)}%`} />
      </div>

      <MarginTester lead={lead} settings={settings} totals={totals} updateLead={updateLead} />

      <Card className="p-5">
        <SectionLabel>Core system — auto-sized from usage data (always included)</SectionLabel>
        {coreLines.some((l) => sizingDeviation(l)) && (
          <div className="flex items-start gap-2 rounded-lg p-2.5 mb-3 text-xs" style={{ background: "#FEF2F2", color: "#991B1B" }}>
            <AlertTriangle size={14} className="shrink-0 mt-0.5" />
            <span>One or more core quantities below have been changed from the calculated requirement (highlighted). Confirm this is intentional before quoting — mismatched sizing is the single biggest source of pricing errors we found auditing past jobs.</span>
          </div>
        )}
        <BomTable lines={coreLines} settings={settings} setOverride={setOverride} lockCategory />
      </Card>

      <Card className="p-5">
        <SectionLabel>Standard catalog — scales automatically, technician can adjust or exclude</SectionLabel>
        <BomTable lines={catalogLines} settings={settings} setOverride={setOverride} groupByCategory />
      </Card>

      <Card className="p-5">
        <div className="flex items-center justify-between mb-3">
          <SectionLabel>Technician additions — unique to this project</SectionLabel>
          <button onClick={addExtra} className="flex items-center gap-1.5 text-sm font-semibold hover:underline" style={{ color: BRAND.navy }}>
            <Plus size={14} /> Add item
          </button>
        </div>
        {extraLines.length === 0 ? (
          <div className="text-sm text-slate-400 py-4 text-center border border-dashed border-slate-200 rounded-lg">No custom items yet — add anything not covered by the standard catalog.</div>
        ) : (
          <div className="space-y-2">
            {lead.extraItems.map((ex) => (
              <div key={ex.id} className="grid grid-cols-12 gap-2 items-center bg-slate-50 rounded-lg p-2">
                <input checked={ex.inc} onChange={(e) => updateExtra(ex.id, { inc: e.target.checked })} type="checkbox" className="col-span-1 justify-self-center" style={{ accentColor: BRAND.navy }} />
                <Input className="col-span-3" placeholder="Category" value={ex.category} onChange={(e) => updateExtra(ex.id, { category: e.target.value })} />
                <Input className="col-span-3" placeholder="Description" value={ex.description} onChange={(e) => updateExtra(ex.id, { description: e.target.value })} />
                <Input className="col-span-1" type="number" placeholder="Qty" value={ex.qty} onChange={(e) => updateExtra(ex.id, { qty: +e.target.value })} />
                <Input className="col-span-2" type="number" placeholder="Unit cost" value={ex.unitCost} onChange={(e) => updateExtra(ex.id, { unitCost: +e.target.value })} />
                <label className="col-span-1 text-xs flex items-center gap-1 text-slate-500 justify-self-center">
                  <input type="checkbox" checked={ex.vatExempt} onChange={(e) => updateExtra(ex.id, { vatExempt: e.target.checked })} style={{ accentColor: BRAND.navy }} /> VAT-ex
                </label>
                <button onClick={() => removeExtra(ex.id)} className="col-span-1 justify-self-end text-slate-300 hover:text-rose-500"><Trash2 size={14} /></button>
              </div>
            ))}
          </div>
        )}
      </Card>

      <div className="flex justify-end">
        <button onClick={onNext} className="flex items-center gap-1.5 text-white px-4 py-2 rounded-lg text-sm font-semibold" style={{ background: BRAND.navy }} onMouseOver={(e)=>e.currentTarget.style.background=BRAND.navyDark} onMouseOut={(e)=>e.currentTarget.style.background=BRAND.navy}>
          Continue to Quotation <ChevronRight size={15} />
        </button>
      </div>
    </div>
  );
}

function Stat({ label, value, tone }) {
  return (
    <Card className={`p-3 text-center ${tone === "navy" ? "border-none" : ""}`} style={tone === "navy" ? { background: BRAND.navy, color: "#FFFFFF" } : {}}>
      <div className={`text-sm font-bold ${tone === "green" ? "text-emerald-600" : ""}`}>{value}</div>
      <div className={`text-xs uppercase tracking-wide ${tone === "navy" ? "text-blue-200" : "text-slate-400"}`}>{label}</div>
    </Card>
  );
}

const CAT_ICON = {
  "PV Structure": <Wrench size={13} />, "Cabling": <Cable size={13} />, "Installation accessories": <Wrench size={13} />, "Logistics & Installation": <Truck size={13} />,
};

function BomTable({ lines, settings, setOverride, groupByCategory, lockCategory }) {
  const groups = groupByCategory
    ? lines.reduce((acc, l) => { (acc[l.category] = acc[l.category] || []).push(l); return acc; }, {})
    : { "": lines };

  return (
    <div className="space-y-4">
      {Object.entries(groups).map(([cat, catLines]) => (
        <div key={cat || "core"}>
          {cat && <div className="flex items-center gap-1.5 text-xs font-semibold text-slate-500 mb-1.5">{CAT_ICON[cat]}{cat}</div>}
          <div className="overflow-x-auto -mx-1">
            <table className="w-full text-sm">
              <thead>
                <tr className="text-left text-xs uppercase tracking-wide text-slate-400 border-b border-slate-200">
                  <th className="py-1.5 px-1 w-8">Inc.</th>
                  <th className="py-1.5 px-1">Description</th>
                  <th className="py-1.5 px-1 w-16 text-right">Qty</th>
                  <th className="py-1.5 px-1 w-24 text-right">Unit cost</th>
                  <th className="py-1.5 px-1 w-24 text-right">Line total</th>
                </tr>
              </thead>
              <tbody>
                {catLines.map((l) => {
                  const dev = sizingDeviation(l);
                  return (
                  <tr key={l.id} className="border-b border-slate-100 last:border-0">
                    <td className="py-1.5 px-1">
                      <input type="checkbox" checked={l.inc} disabled={l.isCore && lockCategory} onChange={(e) => setOverride(l.id, { inc: e.target.checked })} style={{ accentColor: BRAND.navy }} />
                    </td>
                    <td className="py-1.5 px-1 text-slate-700">{l.description}<span className="text-slate-300 ml-1.5 text-xs">{l.quantityRule !== "Fixed" && l.quantityRule !== "Manual" ? `· ${l.quantityRule}` : ""}</span></td>
                    <td className="py-1.5 px-1">
                      <div className="flex items-center justify-end gap-1">
                        {dev && (
                          <span title={`Calculated need: ${l.calcQty}. This is set to ${l.finalQty} (${dev.pct}). Confirm this is intentional.`}>
                            <AlertTriangle size={12} style={{ color: dev.severe ? "#DC2626" : "#D97706" }} />
                          </span>
                        )}
                        <input
                          type="number" value={l.finalQty}
                          onChange={(e) => setOverride(l.id, { qtyOverride: +e.target.value })}
                          className="w-16 text-right rounded px-1.5 py-0.5 text-xs"
                          style={dev ? { border: `1px solid ${dev.severe ? "#FCA5A5" : "#FCD34D"}`, background: dev.severe ? "#FEF2F2" : "#FFFBEB" } : { border: "1px solid #E2E8F0" }}
                        />
                      </div>
                    </td>
                    <td className="py-1.5 px-1">
                      <input type="number" value={l.unitCostUsed} onChange={(e) => setOverride(l.id, { costOverride: +e.target.value })} className="w-24 text-right rounded border border-slate-200 px-1.5 py-0.5 text-xs" />
                    </td>
                    <td className="py-1.5 px-1">
                      <input
                        type="number" value={Math.round(l.lineTotal)}
                        onChange={(e) => {
                          const newTotal = +e.target.value;
                          const qty = l.finalQty > 0 ? l.finalQty : 1;
                          // Back out Unit Cost from whatever markup multiplier is already implied by
                          // this line, so Qty × Unit Cost × markup keeps producing this total exactly —
                          // there's no separate "total" number floating around out of sync with cost.
                          const markupMultiplier = l.unitCostUsed > 0 ? l.unitPrice / l.unitCostUsed : 1 + settings.markup;
                          const newUnitCost = (newTotal / qty) / markupMultiplier;
                          setOverride(l.id, { costOverride: newUnitCost });
                        }}
                        title="Editable directly — useful for items like transport that are really just a flat total. Adjusts Unit Cost behind the scenes so the numbers stay consistent."
                        className="w-24 text-right rounded border border-slate-200 px-1.5 py-0.5 text-xs font-mono font-semibold"
                      />
                    </td>
                  </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      ))}
    </div>
  );
}

